template<class T> class vector
{
  T* first;
  T* last;
  T* limit;
public:
  typedef T* iterator;
  iterator begin() { return first; }
  iterator end() { return last; }
  void push_back(const T& value)
  {
    if (last != limit)
    {
      if (last)
        *last = value;
      ++last;
    }
    else
      _M_insert_aux(last, value);
  }
  void _M_insert_aux(iterator, const T&);
};

template<class Iterator, class T>
Iterator find(Iterator first, Iterator last, const T& value)
{
  while (first != last && !(*first == value))
    ++first;
  return first;
}

class entity
{
public:
  virtual bool possibly_active() const;
  virtual bool possibly_aging() const;
};

class region
{
  char prefix[148];
public:
  typedef vector<entity*> entity_list;
  entity_list possible_active_ents;
  void update_poss_active(entity* e);
};

#define START_PROF_TIMER(timer) ((void)0)
#define STOP_PROF_TIMER(timer) ((void)0)

void region::update_poss_active( entity* e )
{
  START_PROF_TIMER(proftimer_update_poss_active);
  if(e)
  {
    if(e->possibly_active() || e->possibly_aging())
    {
      entity_list::iterator ei_begin = possible_active_ents.begin();
      entity_list::iterator ei_end = possible_active_ents.end();

      entity_list::iterator ei = find( ei_begin, ei_end, e );
      if ( ei == ei_end )
      {
        ei = find( ei_begin, ei_end, (entity*)NULL );
        if ( ei != ei_end )
          *ei = e;
        else
        {
          possible_active_ents.push_back( e );
        }
      }
    }
    else
    {
      entity_list::iterator ei_end = possible_active_ents.end();
      entity_list::iterator ei = find( possible_active_ents.begin(), ei_end, e );
      if ( ei != ei_end )
        *ei = NULL;
    }
  }
  STOP_PROF_TIMER(proftimer_update_poss_active);
}
